 function dialogReason(value){const code=String(value||'').trim(),labels={manager_replied:'Сотрудник ответил вручную',manager_pause:'Сотрудник приостановил AI',human_handoff:'Сотрудник передал диалог человеку',customer_requested_manager:'Клиент запросил сотрудника',trigger_reply_sent_then_handoff:'После ответа AI диалог передан человеку',server_ai_disabled:'AI отключён на сервере',company_ai_disabled:'AI отключён для компании',emergency_stop:'Включена аварийная остановка',tenant_ai_unavailable:'AI недоступен для компании',agent_not_found:'Для диалога не найден агент',agent_disabled:'Агент отключён',ai_emergency_stop:'Включена аварийная остановка',connect_admission_blocked:'Канал или настройки компании не разрешают работу AI',ai_agents_server_disabled:'AI отключён на сервере',conversation_human_or_paused:'Диалог уже остановлен для человека или паузы',newer_inbound:'Получено более новое сообщение клиента'};return labels[code]||code}
