 async function syncChatAgentControl(force=false){if(!profile||!aiAllowed)return;const input=$('deal-chat-input')||$('notice-reply-input'),leadId=String(history.state?.leadId||'').trim();if(!input||!leadId){$('aiAgentChatToggle')?.remove();chatControlInput=input;chatControlLead=leadId;return}if(!force&&input===chatControlInput&&leadId===chatControlLead&&($('aiAgentChatToggle')||Date.now()-chatControlAttempt<5000))return;const request=++chatControlEpoch;chatControlInput=input;chatControlLead=leadId;chatControlAttempt=Date.now();$('aiAgentChatToggle')?.remove();let conversation='';let provider='kommo',channelId='';try{if(!conversation){const owned=await api(`conversations/for-lead/${encodeURIComponent(leadId)}`);conversation=String(owned?.conversation_id||'');provider=String(owned?.provider||'kommo');channelId=String(owned?.channel_id||'')}if(!conversation)return;const routeQuery=new URLSearchParams({provider,channel_id:channelId});const state=await api(`conversations/${encodeURIComponent(conversation)}/state?${routeQuery}`);if(request!==chatControlEpoch||input!==($('deal-chat-input')||$('notice-reply-input'))||String(history.state?.leadId||'')!==leadId)return;const meta=dialogStateMeta(state.display_state||state.state),box=document.createElement('div');box.id='aiAgentChatToggle';box.className='ai-agent-chat-toggle';const summary=document.createElement('div');summary.className='ai-agent-chat-summary';const stateText=document.createElement('span');stateText.className=`ai-agent-chat-state is-${meta.state}`;stateText.textContent=`${state.agent_name||'AI Agent'} · ${meta.label}`;summary.append(stateText);const reason=dialogReason(state.display_reason||state.resume_block_reason||state.reason);if(reason){const detail=document.createElement('small');detail.dataset.reason='';detail.textContent=`Причина: ${reason}`;summary.append(detail)}if(state.updated_at){const detail=document.createElement('small');detail.textContent=`Изменено: ${dialogTime(state.updated_at)}`;summary.append(detail)}box.append(summary);const addAction=(label,action,className='outline')=>{const button=document.createElement('button');button.type='button';button.className=`ai-agent-chat-toggle-button ${className}`;button.textContent=label;button.onclick=async()=>{button.disabled=true;const before=button.textContent;button.textContent='Сохраняю…';try{await setConversationAction(conversation,action,{provider,channelId,reason:action==='pause'?'webapp_chat_pause':action==='handoff'?'webapp_chat_handoff':'webapp_chat_resume'});await syncChatAgentControl(true);await loadHandoffs()}catch(error){button.textContent=error.message;button.disabled=false;setTimeout(()=>{if(!button.disabled)button.textContent=before},2800)}};box.append(button)};if(meta.state==='active'){addAction('Приостановить AI','pause');addAction('Передать человеку','handoff','outline danger')}else if((meta.state==='paused'||meta.state==='human')&&state.resume_allowed!==false){addAction('Возобновить AI','resume','primary')}else if(meta.state==='paused'||meta.state==='human'){const blocked=document.createElement('small');blocked.textContent=`Resume недоступен: ${dialogReason(state.resume_block_reason)||'обязательная блокировка'}`;box.append(blocked)}const field=input.closest('.notice-reply-field')||input.closest('.wa-composer')||input.parentElement,aiButton=field?.querySelector('#notice-reply-ai,#deal-chat-ai');if(aiButton)aiButton.insertAdjacentElement('afterend',box);else field.append(box)}catch{/* The server must resolve a tenant-owned dialogue before exposing control. */}}
